    (''IP_COUR_DESIS'', N''IP courrier desistement'', ''FUSION_RIG'', N''<PARAMETRES LIBELLE_DOCUMENT="IP courrier desistement" TYPE_GENERATION="FUSION_RIG" CODE_PROCESSUS="EDIT_EPI" CODE_ENTITE_SOURCE="EVT_PROC" />'');
